import { useCurrentEditor, useEditorState } from '@tiptap/react'
import { QuoteIcon } from 'lucide-react'
import { memo } from 'react'
import TooltipButton from './tooltip-button'

// Component
const BlockquoteButton = memo(() => {
  // Hooks
  const { editor } = useCurrentEditor()
  const editorState = useEditorState({
    editor,
    selector: ({ editor }) => {
      return {
        isActive: editor?.isActive('blockquote')
      }
    }
  })

  // Template
  return (
    <TooltipButton
      Icon={QuoteIcon}
      isActive={editorState?.isActive}
      kbd='Ctrl Shift B'
      label='Blockquote'
      onClick={() => editor?.chain().focus().toggleBlockquote().run()}
    />
  )
})

BlockquoteButton.displayName = 'BlockquoteButton'
export default BlockquoteButton

import { useCurrentEditor, useEditorState } from '@tiptap/react'
import { BoldIcon } from 'lucide-react'
import { memo } from 'react'
import TooltipButton from './tooltip-button'

// Component
const BoldButton = memo(() => {
  // Hooks
  const { editor } = useCurrentEditor()
  const editorState = useEditorState({
    editor,
    selector: ({ editor }) => {
      return {
        isActive: editor?.isActive('bold')
      }
    }
  })

  // Template
  return (
    <TooltipButton
      Icon={BoldIcon}
      isActive={editorState?.isActive}
      kbd='Ctrl B'
      label='Bold'
      onClick={() => editor?.chain().focus().toggleBold().run()}
    />
  )
})

BoldButton.displayName = 'BoldButton'
export default BoldButton

import Image from '@tiptap/extension-image'
import {
  mergeAttributes,
  NodeViewWrapper,
  type ReactNodeViewProps,
  ReactNodeViewRenderer,
  useCurrentEditor
} from '@tiptap/react'
import { AlignLeftIcon, ChevronDownIcon, TrashIcon } from 'lucide-react'
import { type CSSProperties, type ImgHTMLAttributes, type PointerEvent, useRef, useState } from 'react'
import { Button } from '@/registry/new-york/ui/button/components/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger
} from '@/registry/new-york/ui/dropdown-menu/components/dropdown-menu'
import { Popover, PopoverContent, PopoverTrigger } from '@/registry/new-york/ui/popover/components/popover'
import { Separator } from '@/registry/new-york/ui/separator/components/separator'
import { Skeleton } from '@/registry/new-york/ui/skeleton/components/skeleton'
import { cn } from '@/utils/ui'
import { type Alignment, alignments, containerClassNamePerAlignment, minWidth } from './lib'

// Image attributes
type ImageAttributes = Pick<ImgHTMLAttributes<HTMLImageElement>, 'alt' | 'height' | 'src' | 'title' | 'width'> & {
  alignment: Alignment
  containerStyle: CSSProperties
}

// Resizing position
type ResizingPosition = 'left' | 'right'

// Base resize handler class name
const BASE_RESIZE_HANDLER_CLASS_NAME =
  'invisible absolute top-0 bottom-0 cursor-ew-resize px-2 transition-[visibility_width] group-hover:visible before:absolute before:top-1/2 before:h-1/2 before:max-h-36 before:w-1 before:-translate-y-1/2 before:rounded-md before:bg-muted before:border-muted-foreground before:content-[""]'

// Component
const ImageComponent = ({ node, updateAttributes, deleteNode }: ReactNodeViewProps<HTMLImageElement>) => {
  // Props
  const { alignment, containerStyle, ...imageAttributes } = node.attrs as ImageAttributes

  // Hooks
  const { editor } = useCurrentEditor()

  // Refs
  const containerRef = useRef<HTMLDivElement>(null)

  // States
  const [isLoaded, setIsLoaded] = useState(false)
  const [isOpenPopover, setIsOpenPopover] = useState(false)

  // Methods
  const loadImage = () => {
    setIsLoaded(true)
  }

  const changeAlignment = (alignment: Alignment) => {
    // Update alignment
    updateAttributes({
      alignment
    })

    // Update width (full) if alignment is justify
    if (alignment === 'justify') {
      updateAttributes({
        width: containerRef.current?.clientWidth,
        containerStyle: {
          ...containerStyle,
          width: '100%'
        }
      })
    }

    // Focus editor
    editor?.commands.focus()
  }

  const downPointer = (pointerDownEvent: PointerEvent<HTMLDivElement>, position: ResizingPosition) => {
    pointerDownEvent.preventDefault()
    pointerDownEvent.stopPropagation()

    // Handle move pointer
    const handleMovePointer = (pointerMoveEvent: MouseEvent) => {
      pointerMoveEvent.preventDefault()
      pointerMoveEvent.stopPropagation()

      const containerWidth = containerRef.current?.clientWidth ?? 0
      const deltaX =
        (position === 'left'
          ? pointerDownEvent.clientX - pointerMoveEvent.clientX
          : pointerMoveEvent.clientX - pointerDownEvent.clientX) * 2
      const newWidth = Math.round(
        Math.max(minWidth, Math.min(containerWidth, (imageAttributes.width as number) + deltaX))
      )

      updateAttributes({
        width: newWidth,
        containerStyle: {
          ...containerStyle,
          width: `${Math.round((newWidth * 100) / containerWidth)}%`
        }
      })
    }

    // Handle up pointer
    const handleUpPointer = (pointerUpEvent: MouseEvent) => {
      pointerUpEvent.preventDefault()
      pointerUpEvent.stopPropagation()

      editor?.commands.focus()

      document.removeEventListener('pointermove', handleMovePointer)
      document.removeEventListener('pointerup', handleUpPointer)
    }

    document.addEventListener('pointermove', handleMovePointer)
    document.addEventListener('pointerup', handleUpPointer)
  }

  const deleteImage = () => {
    deleteNode()
    editor?.commands.focus()
  }

  // Template
  return (
    <NodeViewWrapper data-drag-handle>
      <div className={cn('flex', containerClassNamePerAlignment[alignment])} ref={containerRef}>
        <div className='group relative transition-all' style={containerStyle}>
          {!isLoaded && <Skeleton className='absolute inset-0 rounded-md' />}

          <Popover onOpenChange={setIsOpenPopover} open={isOpenPopover}>
            <PopoverTrigger className='w-full'>
              {/** biome-ignore lint/correctness/useImageSize:ignore */}
              {/** biome-ignore lint/a11y/noNoninteractiveElementInteractions: ignore */}
              <img
                {...imageAttributes}
                alt='Alt'
                className={cn(
                  'peer pointer-events-none w-full object-contain opacity-0 outline-2 outline-transparent outline-offset-2 transition-all',
                  {
                    'outline-inherit': isOpenPopover,
                    'pointer-events-auto opacity-100': isLoaded
                  }
                )}
                onLoad={loadImage}
              />
            </PopoverTrigger>

            <PopoverContent className='space-y-4' side='top'>
              <div className='flex gap-2'>
                {/* Alignment */}
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button variant='outline'>
                      <AlignLeftIcon />
                      <ChevronDownIcon />
                    </Button>
                  </DropdownMenuTrigger>

                  <DropdownMenuContent>
                    {alignments.map((alignmentOption) => (
                      <DropdownMenuItem
                        className={cn({
                          'bg-accent': alignment === alignmentOption.value
                        })}
                        key={alignmentOption.value}
                        onClick={() => changeAlignment(alignmentOption.value)}
                      >
                        <alignmentOption.icon />
                        <span>{alignmentOption.label}</span>
                      </DropdownMenuItem>
                    ))}
                  </DropdownMenuContent>
                </DropdownMenu>

                <Separator className='h-10' orientation='vertical' />

                {/* Trash */}
                <Button onClick={deleteImage} size='icon' variant='outline'>
                  <TrashIcon />
                </Button>
              </div>
            </PopoverContent>
          </Popover>

          <div
            className={cn('left-1 before:left-1.5', BASE_RESIZE_HANDLER_CLASS_NAME)}
            onPointerDown={(e) => downPointer(e, 'left')}
          />

          <div
            className={cn('right-1 before:right-1.5', BASE_RESIZE_HANDLER_CLASS_NAME)}
            onPointerDown={(e) => downPointer(e, 'right')}
          />
        </div>
      </div>
    </NodeViewWrapper>
  )
}

// Extension
const CustomImageExtension = Image.extend({
  renderHTML({ HTMLAttributes }) {
    const { alignment, containerStyle, ...imageAttributes } = HTMLAttributes as ImageAttributes
    return [
      'div',
      {
        class: cn('flex', containerClassNamePerAlignment[alignment])
      },
      [
        'div',
        {
          style: Object.entries(containerStyle)
            .map(([key, value]) => `${key}: ${value}`)
            .join(';')
        },
        [
          'img',
          {
            ...mergeAttributes(imageAttributes),
            class: 'w-full object-contain rounded-md'
          }
        ]
      ]
    ]
  },
  addAttributes() {
    return {
      ...this.parent?.(),
      width: {
        default: minWidth
      },
      alignment: {
        default: 'center'
      },
      containerStyle: {
        default: {
          width: `${minWidth}px`
        }
      }
    }
  },
  addNodeView() {
    return ReactNodeViewRenderer(ImageComponent)
  }
})

export default CustomImageExtension

import Youtube from '@tiptap/extension-youtube'
import {
  mergeAttributes,
  NodeViewWrapper,
  type ReactNodeViewProps,
  ReactNodeViewRenderer,
  useCurrentEditor
} from '@tiptap/react'
import { AlignLeftIcon, ChevronDownIcon, MoveHorizontalIcon, TrashIcon } from 'lucide-react'
import { type CSSProperties, type IframeHTMLAttributes, useRef, useState } from 'react'
import { Button } from '@/registry/new-york/ui/button/components/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger
} from '@/registry/new-york/ui/dropdown-menu/components/dropdown-menu'
import { Popover, PopoverContent, PopoverTrigger } from '@/registry/new-york/ui/popover/components/popover'
import { Separator } from '@/registry/new-york/ui/separator/components/separator'
import { Skeleton } from '@/registry/new-york/ui/skeleton/components/skeleton'
import { cn } from '@/utils/ui'
import { type Alignment, alignments, containerClassNamePerAlignment, isValidYoutubeUrl, minWidth } from './lib'

// Youtube attributes
type YoutubeAttributes = IframeHTMLAttributes<HTMLIFrameElement> & {
  alignment: Alignment
  containerStyle: CSSProperties
}

// Width sizes
const widthSizes: string[] = ['25%', '50%', '75%', '100%']

// Get youtube embed url
export const getYoutubeEmbedUrl = (nocookie?: boolean, isPlaylist?: boolean) => {
  if (isPlaylist) {
    return 'https://www.youtube-nocookie.com/embed/videoseries?list='
  }
  return nocookie ? 'https://www.youtube-nocookie.com/embed/' : 'https://www.youtube.com/embed/'
}

// Get embed url from youtube url
const getEmbedUrlFromYoutubeUrl = (options: {
  url: string
  allowFullscreen?: boolean
  autoplay?: boolean
  ccLanguage?: string
  ccLoadPolicy?: boolean
  controls?: boolean
  disableKBcontrols?: boolean
  enableIFrameApi?: boolean
  endTime?: number
  interfaceLanguage?: string
  ivLoadPolicy?: number
  loop?: boolean
  modestBranding?: boolean
  nocookie?: boolean
  origin?: string
  playlist?: string
  progressBarColor?: string
  startAt?: number
  rel?: number
}) => {
  const {
    url,
    allowFullscreen,
    autoplay,
    ccLanguage,
    ccLoadPolicy,
    controls,
    disableKBcontrols,
    enableIFrameApi,
    endTime,
    interfaceLanguage,
    ivLoadPolicy,
    loop,
    modestBranding,
    nocookie,
    origin,
    playlist,
    progressBarColor,
    startAt,
    rel
  } = options

  if (!isValidYoutubeUrl(url)) {
    return null
  }

  // If is already an embed url, return it
  if (url.includes('/embed/')) {
    return url
  }

  // If is a youtu.be url, get the id after the /
  if (url.includes('youtu.be')) {
    const id = url.split('/').pop()

    if (!id) {
      return null
    }
    return `${getYoutubeEmbedUrl(nocookie)}${id}`
  }

  const videoIdRegex = /(?:(v|list)=|shorts\/)([-\w]+)/gm
  const matches = videoIdRegex.exec(url)

  if (!matches?.[2]) {
    return null
  }

  let outputUrl = `${getYoutubeEmbedUrl(nocookie, matches[1] === 'list')}${matches[2]}`

  const params: string[] = []

  if (allowFullscreen === false) {
    params.push('fs=0')
  }

  if (autoplay) {
    params.push('autoplay=1')
  }

  if (ccLanguage) {
    params.push(`cc_lang_pref=${ccLanguage}`)
  }

  if (ccLoadPolicy) {
    params.push('cc_load_policy=1')
  }

  if (!controls) {
    params.push('controls=0')
  }

  if (disableKBcontrols) {
    params.push('disablekb=1')
  }

  if (enableIFrameApi) {
    params.push('enablejsapi=1')
  }

  if (endTime) {
    params.push(`end=${endTime}`)
  }

  if (interfaceLanguage) {
    params.push(`hl=${interfaceLanguage}`)
  }

  if (ivLoadPolicy) {
    params.push(`iv_load_policy=${ivLoadPolicy}`)
  }

  if (loop) {
    params.push('loop=1')
  }

  if (modestBranding) {
    params.push('modestbranding=1')
  }

  if (origin) {
    params.push(`origin=${origin}`)
  }

  if (playlist) {
    params.push(`playlist=${playlist}`)
  }

  if (startAt) {
    params.push(`start=${startAt}`)
  }

  if (progressBarColor) {
    params.push(`color=${progressBarColor}`)
  }

  if (rel !== undefined) {
    params.push(`rel=${rel}`)
  }

  if (params.length) {
    outputUrl += `${matches[1] === 'v' ? '?' : '&'}${params.join('&')}`
  }

  return outputUrl
}

// Component
const YoutubeComponent = (props: ReactNodeViewProps<HTMLImageElement>) => {
  // Props
  const { node, updateAttributes, deleteNode } = props
  const { alignment, containerStyle, ...youtubeAttributes } = node.attrs as YoutubeAttributes

  // Hooks
  const { editor } = useCurrentEditor()

  // Refs
  const containerRef = useRef<HTMLDivElement>(null)

  // States
  const [src] = useState(
    () =>
      getEmbedUrlFromYoutubeUrl({
        url: youtubeAttributes.src as string,
        nocookie: true
      }) ?? undefined
  )
  const [isLoaded, setIsLoaded] = useState(false)
  const [isOpenPopover, setIsOpenPopover] = useState(false)

  // Methods
  // Handle load video
  const handleLoadVideo = () => {
    setIsLoaded(true)
  }

  // Handle change alignment
  const handleChangeAlignment = (alignment: Alignment) => {
    // Update alignment
    updateAttributes({
      alignment
    })

    // Update width (full) if alignment is justify
    if (alignment === 'justify') {
      updateAttributes({
        width: containerRef.current?.clientWidth,
        containerStyle: {
          ...containerStyle,
          width: '100%'
        }
      })
    }

    // Focus editor
    editor?.commands.focus()
  }

  // Handle change width size
  const handleChangeWidthSize = (size: string) => {
    updateAttributes({
      containerStyle: {
        ...containerStyle,
        width: size
      }
    })
    editor?.commands.focus()
  }

  // Handle delete video
  const handleDeleteVideo = () => {
    deleteNode()
    editor?.commands.focus()
  }

  // Template
  return (
    <NodeViewWrapper data-drag-handle>
      <div className={cn('flex', containerClassNamePerAlignment[alignment])} ref={containerRef}>
        <Popover onOpenChange={setIsOpenPopover} open={isOpenPopover}>
          <PopoverTrigger
            className={cn('group relative aspect-video rounded-md border p-6 transition-all', {
              'border-primary': isOpenPopover,
              'pointer-events-auto opacity-100': isLoaded
            })}
            style={containerStyle}
          >
            {!isLoaded && <Skeleton className='pointer-events-none absolute inset-0 rounded-md' />}

            {/** biome-ignore lint/a11y/noNoninteractiveElementInteractions: ignore */}
            <iframe
              allowFullScreen={false}
              className='size-full rounded-md object-contain'
              height={youtubeAttributes.height}
              onLoad={handleLoadVideo}
              src={src}
              title='custom-youtube-extension'
              width={youtubeAttributes.width}
            />
          </PopoverTrigger>

          <PopoverContent className='space-y-4' side='top'>
            <div className='flex gap-2'>
              {/* Alignment */}
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant='outline'>
                    <AlignLeftIcon />
                    <ChevronDownIcon />
                  </Button>
                </DropdownMenuTrigger>

                <DropdownMenuContent>
                  {alignments.map((alignmentOption) => (
                    <DropdownMenuItem
                      className={cn({
                        'bg-accent': alignment === alignmentOption.value
                      })}
                      key={alignmentOption.value}
                      onClick={() => handleChangeAlignment(alignmentOption.value)}
                    >
                      <alignmentOption.icon />
                      <span>{alignmentOption.label}</span>
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>

              <Separator className='h-10' orientation='vertical' />

              {/* Width size */}
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant='outline'>
                    <MoveHorizontalIcon />
                    <ChevronDownIcon />
                  </Button>
                </DropdownMenuTrigger>

                <DropdownMenuContent>
                  {widthSizes.map((size) => (
                    <DropdownMenuItem
                      className={cn({
                        'bg-accent': containerStyle.width === size
                      })}
                      key={size}
                      onClick={() => handleChangeWidthSize(size)}
                    >
                      {size}
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>

              <Separator className='h-10' orientation='vertical' />

              {/* Trash */}
              <Button onClick={handleDeleteVideo} size='icon' variant='outline'>
                <TrashIcon />
              </Button>
            </div>
          </PopoverContent>
        </Popover>
      </div>
    </NodeViewWrapper>
  )
}

// Extension
export const CustomYoutubeExtension = Youtube.extend({
  renderHTML({ HTMLAttributes }) {
    const { alignment, containerStyle, ...youtubeAttributes } = HTMLAttributes as YoutubeAttributes

    const embedUrl = getEmbedUrlFromYoutubeUrl({
      url: HTMLAttributes.src,
      allowFullscreen: this.options.allowFullscreen,
      autoplay: this.options.autoplay,
      ccLanguage: this.options.ccLanguage,
      ccLoadPolicy: this.options.ccLoadPolicy,
      controls: this.options.controls,
      disableKBcontrols: this.options.disableKBcontrols,
      enableIFrameApi: this.options.enableIFrameApi,
      endTime: this.options.endTime,
      interfaceLanguage: this.options.interfaceLanguage,
      ivLoadPolicy: this.options.ivLoadPolicy,
      loop: this.options.loop,
      modestBranding: this.options.modestBranding,
      nocookie: this.options.nocookie,
      origin: this.options.origin,
      playlist: this.options.playlist,
      progressBarColor: this.options.progressBarColor,
      startAt: HTMLAttributes.start || 0,
      rel: this.options.rel
    })

    if (embedUrl) {
      youtubeAttributes.src = embedUrl
    }

    return [
      'div',
      {
        class: cn('flex', containerClassNamePerAlignment[alignment])
      },
      [
        'div',
        {
          class: 'aspect-video',
          style: Object.entries(containerStyle)
            .map(([key, value]) => `${key}: ${value}`)
            .join(';')
        },
        [
          'iframe',
          {
            ...mergeAttributes(
              this.options.HTMLAttributes,
              {
                width: this.options.width,
                height: this.options.height,
                allowfullscreen: this.options.allowFullscreen,
                autoplay: this.options.autoplay,
                ccLanguage: this.options.ccLanguage,
                ccLoadPolicy: this.options.ccLoadPolicy,
                disableKBcontrols: this.options.disableKBcontrols,
                enableIFrameApi: this.options.enableIFrameApi,
                endTime: this.options.endTime,
                interfaceLanguage: this.options.interfaceLanguage,
                ivLoadPolicy: this.options.ivLoadPolicy,
                loop: this.options.loop,
                modestBranding: this.options.modestBranding,
                origin: this.options.origin,
                playlist: this.options.playlist,
                progressBarColor: this.options.progressBarColor,
                rel: this.options.rel
              },
              youtubeAttributes
            ),
            class: 'size-full rounded-md object-contain'
          }
        ]
      ]
    ]
  },
  addAttributes() {
    return {
      ...this.parent?.(),
      alignment: {
        default: 'center'
      },
      containerStyle: {
        default: {
          width: `${minWidth}px`
        }
      }
    }
  },
  addNodeView() {
    return ReactNodeViewRenderer(YoutubeComponent)
  }
})

export default CustomYoutubeExtension

import type { Content } from '@tiptap/react'
import parse from 'html-react-parser'

// Editor content
export const EditorContent = ({ content }: { content: Content }) => {
  // Template
  if (typeof content === 'string') {
    return <div className='tiptap'>{parse(content)}</div>
  }
  return null
}

import {
  type Content,
  type Extensions,
  EditorContext as TiptapEditorContext,
  type UseEditorOptions,
  useEditor
} from '@tiptap/react'
import throttle from 'lodash.throttle'
import { type Dispatch, type RefObject, type SetStateAction, useId, useMemo, useRef, useState } from 'react'
import { Spinner } from '@/registry/new-york/ui/spinner/components/spinner'
import BlockquoteButton from './blockquote-button'
import BoldButton from './bold-button'
import FileButton from './file-button'
import HighlightButton from './highlight-button'
import HistoryButtons from './history-buttons'
import ImageButton from './image-button'
import InternalEditorContent from './internal-editor-content'
import ItalicButton from './italic-button'
import { defaultExtensions, getEditorValue } from './lib'
import LinkButton from './link-button'
import ListButton from './list-button'
import PreviewButton from './preview-button'
import StrikeButton from './strike-button'
import TableButton from './table-button'
import TextAlignButton from './text-align-button'
import TextColorButton from './text-color-button'
import TextStyleButton from './text-style-button'
import ToolbarSeparator from './toolbar-separator'
import UnderlineButton from './underline-button'
import YoutubeButton from './youtube-button'
import ZoomButton from './zoom-button'

// Editor
export type EditorProps = UseEditorOptions & {
  value: Content
  onValueChange: (value: Content) => void
}

export type CallbackRef = RefObject<((editor: ReturnType<typeof useEditor> | null) => void) | null>

export type SetExtensions = Dispatch<SetStateAction<Extensions>>

export const Editor = ({ value, onValueChange, ...props }: EditorProps) => {
  // Hooks
  const id = useId()

  // Refs
  const callbackRef = useRef<CallbackRef['current']>(null)

  // States
  const [extensions, setExtensions] = useState<Extensions>(defaultExtensions)

  // Hooks
  const editor = useEditor(
    {
      extensions,
      editorProps: {
        attributes: {
          autocomplete: 'off',
          autocorrect: 'off',
          autocapitalize: 'off'
        }
      },
      immediatelyRender: false,
      onUpdate: useMemo(() => {
        return throttle(
          ({ editor }) => {
            onValueChange(getEditorValue(editor, 'html'))
          },
          1000,
          {
            trailing: false
          }
        )
      }, [onValueChange]),
      onCreate: ({ editor }) => {
        if (value && editor.isEmpty) {
          editor.commands.setContent(value)
        }
        callbackRef.current?.(editor)
        callbackRef.current = null
      },
      onBlur: ({ editor }) => {
        onValueChange(getEditorValue(editor, 'html'))
      },
      ...props
    },
    [extensions]
  )

  // Template
  if (!editor) {
    return <Spinner className='mx-auto size-6' />
  }

  return (
    <TiptapEditorContext value={{ editor }}>
      <div
        className='w-full transition-all [&_.tiptap]:max-h-[500px] [&_.tiptap]:min-h-64 [&_.tiptap]:overflow-auto [&_.tiptap]:border-none [&_.tiptap]:p-6 [&_.tiptap]:outline-none'
        id={`editor-${id}`}
      >
        <div className='text rounded-md border border-input text-foreground ring-offset-background transition-[color,box-shadow] placeholder:text-muted-foreground has-[.ProseMirror-focused]:border-ring has-[.ProseMirror-focused]:ring-[3px] has-[.ProseMirror-focused]:ring-ring/50 group-data-[invalid=true]/field:border-destructive group-data-[invalid=true]/field:ring-destructive/20 group-data-[invalid=true]/field:has-[.ProseMirror-focused]:border-destructive group-data-[invalid=true]/field:dark:ring-destructive/40'>
          <div className='flex flex-wrap items-center gap-1 border-input border-b p-4'>
            <HistoryButtons />
            <ToolbarSeparator />

            <BoldButton />
            <ItalicButton />
            <UnderlineButton />
            <StrikeButton />
            <BlockquoteButton />
            <ToolbarSeparator />

            <TextStyleButton />
            <TextAlignButton callbackRef={callbackRef} setExtensions={setExtensions} />
            <TextColorButton />
            <HighlightButton />
            <ToolbarSeparator />

            <LinkButton id={id} />
            <ListButton />
            <TableButton callbackRef={callbackRef} setExtensions={setExtensions} />
            <YoutubeButton callbackRef={callbackRef} id={id} setExtensions={setExtensions} />
            <ImageButton id={id} />
            <FileButton id={id} />
            <ToolbarSeparator />

            <ZoomButton id={id} />
            <PreviewButton value={value} />
          </div>

          <InternalEditorContent />
        </div>
      </div>
    </TiptapEditorContext>
  )
}

import { useForm } from '@tanstack/react-form'
import { useCurrentEditor } from '@tiptap/react'
import { CheckCircleIcon, PaperclipIcon } from 'lucide-react'
import { memo, useState } from 'react'
import type { DropzoneOptions } from 'react-dropzone'
import { toast } from 'sonner'
import z from 'zod'
import {
  FileUpload,
  FileUploadContent,
  FileUploadInput,
  FileUploadItem,
  type FileUploadProps
} from '@/registry/new-york/molecules/file-upload/components/file-upload'
import { getFileUrl, type UploadedFile, useFileUpload } from '@/registry/new-york/molecules/file-upload/components/lib'
import { Button } from '@/registry/new-york/ui/button/components/button'
import { Field, FieldError, FieldLabel } from '@/registry/new-york/ui/field/components/field'
import { Popover, PopoverContent, PopoverTrigger } from '@/registry/new-york/ui/popover/components/popover'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/registry/new-york/ui/tooltip/components/tooltip'

// File form schema
export const fileFormSchema = z.object({
  files: z.array(z.custom<File>()).min(1, 'Please select the file')
})

// Default file form value
export const defaultFileFormValue: z.input<typeof fileFormSchema> = {
  files: []
}

// File uploader dropzone options
export const fileUploaderDropzoneOptions: DropzoneOptions = {
  maxFiles: 10,
  multiple: true,
  accept: {
    'application/msword': ['.doc'],
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document': ['.docx'],
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'],
    'application/xml': ['.xml'],
    'application/pdf': ['.pdf']
  }
}

// Component
const FileButton = memo<{
  id: string
}>(({ id }) => {
  // Hooks
  const { editor } = useCurrentEditor()
  const { isUploadFilePending, uploadFile } = useFileUpload()

  // States
  const [isOpenPopover, setIsOpenPopover] = useState(false)

  // Form
  const fileForm = useForm({
    formId: `${id}-file-form`,
    defaultValues: defaultFileFormValue,
    validators: {
      onSubmit: fileFormSchema
    },
    onSubmit: async ({ value }) => {
      try {
        const { files } = fileFormSchema.parse(value)

        // Upload file
        const uploadedFiles = (await Promise.all(files.map(async (file) => await uploadFile(file)))).filter(
          Boolean
        ) as UploadedFile[]

        // Add file node view
        for (const uploadedFile of uploadedFiles) {
          editor
            ?.chain()
            .focus()
            // @ts-expect-error - custom command from FileExtension
            .insertFile({
              url: getFileUrl(uploadedFile.path),
              name: uploadedFile.original,
              mime: uploadedFile.mime,
              size: uploadedFile.compress_info[''].size
            })
            .run()
        }

        // Enter new line
        if (uploadedFiles.length > 0) {
          editor?.commands.enter()
        }

        // Close popover
        setIsOpenPopover(false)
      } catch {
        toast.error('Failure', {
          description: 'An error occurred, please try again'
        })
      }
    }
  })

  // Template
  return (
    <Popover onOpenChange={setIsOpenPopover} open={isOpenPopover}>
      <Tooltip>
        <TooltipTrigger asChild>
          <PopoverTrigger asChild>
            <Button size='icon' variant='ghost'>
              <PaperclipIcon />
            </Button>
          </PopoverTrigger>
        </TooltipTrigger>

        <TooltipContent>File</TooltipContent>
      </Tooltip>

      <PopoverContent className='w-xs space-y-6' onCloseAutoFocus={() => fileForm.reset()}>
        <div>Acceptable formats: doc, docx, xlsx, xml, pdf</div>

        <form
          id={fileForm.formId}
          onSubmit={(e) => {
            e.preventDefault()
            fileForm.handleSubmit()
          }}
        >
          <fileForm.Field name='files'>
            {(field) => {
              const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
              return (
                <Field data-invalid={isInvalid}>
                  <FieldLabel htmlFor={`editor-${fileForm.formId}-files`}>Files *</FieldLabel>

                  <FileUpload
                    className='xl:grid-cols-1'
                    dropzoneOptions={fileUploaderDropzoneOptions}
                    onValueChange={field.handleChange as FileUploadProps['onValueChange']}
                    value={field.state.value}
                  >
                    <FileUploadInput aria-invalid={isInvalid} id={`editor-${fileForm.formId}-files`} />
                    <FileUploadContent>
                      {field.state.value.map((value, index) => (
                        <FileUploadItem
                          index={index}
                          // biome-ignore lint/suspicious/noArrayIndexKey: ignore
                          key={index}
                          value={value}
                        />
                      ))}
                    </FileUploadContent>
                  </FileUpload>

                  {isInvalid && <FieldError errors={field.state.meta.errors} />}
                </Field>
              )
            }}
          </fileForm.Field>
        </form>

        <div className='flex items-center justify-end gap-1'>
          <fileForm.Subscribe selector={(state) => [state.canSubmit, state.isSubmitting]}>
            {([canSubmit, isSubmitting]) => (
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    disabled={!canSubmit}
                    form={fileForm.formId}
                    isLoading={isUploadFilePending || isSubmitting}
                    size='icon'
                    type='submit'
                    variant='outline'
                  >
                    <CheckCircleIcon />
                  </Button>
                </TooltipTrigger>
                <TooltipContent>submitButton</TooltipContent>
              </Tooltip>
            )}
          </fileForm.Subscribe>
        </div>
      </PopoverContent>
    </Popover>
  )
})

FileButton.displayName = 'FileButton'
export default FileButton

import {
  type CommandProps,
  mergeAttributes,
  Node,
  NodeViewWrapper,
  type ReactNodeViewProps,
  ReactNodeViewRenderer,
  useCurrentEditor
} from '@tiptap/react'
import { PaperclipIcon, TrashIcon } from 'lucide-react'
import type { MouseEventHandler } from 'react'
import type { FileAttributes } from '@/@types/tiptap'
import { getSizeText } from '@/registry/new-york/molecules/file-upload/components/lib'
import { Button } from '@/registry/new-york/ui/button/components/button'

// Component
const FileComponent = (props: ReactNodeViewProps<HTMLAnchorElement>) => {
  const { node, deleteNode } = props
  const nodeAttrs = node.attrs as FileAttributes

  // Hooks
  const { editor } = useCurrentEditor()

  // Methods
  const deleteFile: MouseEventHandler<HTMLButtonElement> = (e) => {
    e.preventDefault()
    e.stopPropagation()

    deleteNode()
    editor?.commands.focus()
  }

  // Template
  return (
    <NodeViewWrapper>
      <a
        className='flex w-full items-center gap-4 rounded-md border p-4 transition-colors duration-200 hover:bg-gray-200 hover:no-underline'
        href={nodeAttrs.url}
        rel='noreferrer'
        target='_blank'
      >
        <PaperclipIcon className='size-4' />

        <div className='grow space-y-2 overflow-hidden'>
          <div className='line-clamp-1'>{nodeAttrs.name}</div>
          <div>{getSizeText(nodeAttrs.size)}</div>
        </div>

        <Button onClick={deleteFile} size='icon' variant='ghost'>
          <TrashIcon />
        </Button>
      </a>
    </NodeViewWrapper>
  )
}

// Extension
const FileExtension = Node.create({
  name: 'file',
  group: 'block',
  selectable: true,
  draggable: true,
  addOptions() {
    return {
      HTMLAttributes: {
        target: '_blank',
        rel: 'noreferrer'
      }
    }
  },
  addAttributes() {
    return {
      url: {
        default: null
      },
      name: {
        default: null
      },
      mime: {
        default: null
      },
      size: {
        default: 0
      }
    }
  },
  parseHTML() {
    return [
      {
        tag: 'a'
      }
    ]
  },
  renderHTML({ HTMLAttributes }) {
    const { url, name, size } = HTMLAttributes as FileAttributes

    return [
      'a',
      mergeAttributes(this.options.HTMLAttributes, {
        href: url,
        class:
          'flex items-center gap-4 rounded-md border p-4 transition-colors duration-200 hover:bg-gray-200 hover:no-underline'
      }),
      [
        'svg',
        {
          xmlns: 'http://www.w3.org/2000/svg',
          width: '24',
          height: '24',
          viewBox: '0 0 24 24',
          fill: 'none',
          stroke: 'currentColor',
          'stroke-width': '2',
          'stroke-linecap': 'round',
          'stroke-linejoin': 'round',
          class: 'lucide lucide-paperclip-icon lucide-paperclip size-4'
        },
        [
          'path',
          {
            d: 'm16 6-8.414 8.586a2 2 0 0 0 2.829 2.829l8.414-8.586a4 4 0 1 0-5.657-5.657l-8.379 8.551a6 6 0 1 0 8.485 8.485l8.379-8.551'
          }
        ]
      ],
      [
        'div',
        {
          class: 'space-y-2'
        },
        ['div', name],
        ['div', getSizeText(size)]
      ]
    ]
  },
  // @ts-expect-error - tiptap custom command not in core type definitions
  addCommands() {
    return {
      insertFile:
        (options: FileAttributes) =>
        ({ commands }: CommandProps) => {
          return commands.insertContent({
            type: this.name,
            attrs: {
              ...options
            }
          })
        }
    }
  },
  addNodeView() {
    return ReactNodeViewRenderer(FileComponent)
  }
})

export default FileExtension

