import { useCurrentEditor } from '@tiptap/react'
import { TableIcon } from 'lucide-react'
import { memo, useRef, useTransition } from 'react'
import type { CallbackRef, SetExtensions } from './editor'
import TooltipButton from './tooltip-button'

// Component
const TableButton = memo<{
  callbackRef: CallbackRef
  setExtensions: SetExtensions
}>(({ callbackRef, setExtensions }) => {
  // Hooks
  const { editor } = useCurrentEditor()
  const [isPending, startTransition] = useTransition()

  // Refs
  const isExtensionLoadedRef = useRef(false)

  // Template
  return (
    <TooltipButton
      Icon={TableIcon}
      isLoading={isPending}
      label='Table'
      onClick={() => {
        const callback: CallbackRef['current'] = (editor) => {
          editor?.chain().focus().insertTable({ rows: 3, cols: 3, withHeaderRow: true }).run()
        }

        if (isExtensionLoadedRef.current) {
          return callback(editor)
        }

        // Load extension
        startTransition(async () => {
          try {
            const { TableKit } = await import('@tiptap/extension-table')
            callbackRef.current = callback
            setExtensions((prev) => [
              ...prev,
              TableKit.configure({
                table: { resizable: true, allowTableNodeSelection: true }
              })
            ])
            isExtensionLoadedRef.current = true
          } catch (error) {
            console.error('An error occurred when load the TableKit extension', error)
          }
        })
      }}
    />
  )
})

TableButton.displayName = 'TableButton'
export default TableButton

import { useCurrentEditor, useEditorState } from '@tiptap/react'
import { AlignLeft, ChevronDown } from 'lucide-react'
import { memo, useRef, useTransition } from 'react'
import { Button } from '@/registry/new-york/ui/button/components/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuShortcut,
  DropdownMenuTrigger
} from '@/registry/new-york/ui/dropdown-menu/components/dropdown-menu'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/registry/new-york/ui/tooltip/components/tooltip'
import { cn } from '@/utils/ui'
import type { CallbackRef, SetExtensions } from './editor'
import { alignments } from './lib'

// Component
const TextAlignButton = memo<{
  setExtensions: SetExtensions
  callbackRef: CallbackRef
}>(({ callbackRef, setExtensions }) => {
  // Hooks
  const { editor } = useCurrentEditor()
  const editorState = useEditorState({
    editor,
    selector: ({ editor }) => {
      return {
        isActive: {
          left: editor?.isActive({ textAlign: 'left' }),
          center: editor?.isActive({ textAlign: 'center' }),
          right: editor?.isActive({ textAlign: 'right' }),
          justify: editor?.isActive({ textAlign: 'justify' })
        }
      }
    }
  })
  const [isPending, startTransition] = useTransition()

  // Refs
  const isExtensionLoadedRef = useRef(false)

  // Template
  return (
    <DropdownMenu>
      <Tooltip>
        <TooltipTrigger asChild>
          <DropdownMenuTrigger asChild>
            <Button className='gap-1' isLoading={isPending} variant='ghost'>
              <AlignLeft />
              <ChevronDown />
            </Button>
          </DropdownMenuTrigger>
        </TooltipTrigger>

        <TooltipContent>Text alignment</TooltipContent>
      </Tooltip>

      <DropdownMenuContent>
        {alignments.map((alignment) => (
          <DropdownMenuItem
            className={cn({
              'bg-accent text-accent-foreground': editorState?.isActive[alignment.value]
            })}
            key={alignment.value}
            onClick={() => {
              const callback: CallbackRef['current'] = (editor) => {
                editor?.chain().focus().setTextAlign(alignment.value).run()
              }

              if (isExtensionLoadedRef.current) {
                return callback(editor)
              }

              // Load extension
              startTransition(async () => {
                try {
                  const extension = await import('@tiptap/extension-text-align')

                  callbackRef.current = callback

                  setExtensions((prev) => [
                    ...prev,
                    extension.default.configure({
                      types: ['heading', 'paragraph']
                    })
                  ])

                  isExtensionLoadedRef.current = true
                } catch (error) {
                  console.error('An error occurred when load the TextAlign extension', error)
                }
              })
            }}
          >
            <alignment.icon />
            <span>{alignment.label}</span>
            <DropdownMenuShortcut>{alignment.shortcut}</DropdownMenuShortcut>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
})

TextAlignButton.displayName = 'TextAlignButton'
export default TextAlignButton

import type { Level } from '@tiptap/extension-heading'
import { useCurrentEditor, useEditorState } from '@tiptap/react'
import { ChevronDownIcon, TypeIcon } from 'lucide-react'
import { memo } from 'react'
import { Button } from '@/registry/new-york/ui/button/components/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuShortcut,
  DropdownMenuTrigger
} from '@/registry/new-york/ui/dropdown-menu/components/dropdown-menu'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/registry/new-york/ui/tooltip/components/tooltip'
import { cn } from '@/utils/ui'

// Text styles
const textStyles: Array<{
  label: string
  level: Level | null
  shortcut: string
}> = [
  {
    label: 'Normal text',
    level: null,
    shortcut: 'Ctrl Alt 0'
  },
  {
    label: 'Heading 1',
    level: 1,
    shortcut: 'Ctrl Alt 1'
  },
  {
    label: 'Heading 2',
    level: 2,
    shortcut: 'Ctrl Alt 2'
  },
  {
    label: 'Heading 3',
    level: 3,
    shortcut: 'Ctrl Alt 3'
  },
  {
    label: 'Heading 4',
    level: 4,
    shortcut: 'Ctrl Alt 4'
  }
]

// Component
const TextStyleButton = memo(() => {
  // Hooks
  const { editor } = useCurrentEditor()
  const editorState = useEditorState({
    editor,
    selector: ({ editor }) => {
      return {
        isActive: {
          null: editor?.isActive('paragraph'),
          1: editor?.isActive('heading', { level: 1 }),
          2: editor?.isActive('heading', { level: 2 }),
          3: editor?.isActive('heading', { level: 3 }),
          4: editor?.isActive('heading', { level: 4 }),
          5: editor?.isActive('heading', { level: 5 }),
          6: editor?.isActive('heading', { level: 6 })
        }
      }
    }
  })

  // Methods
  const changeTextStyle = (textStyle: (typeof textStyles)[number]) => {
    const { level } = textStyle
    if (level) {
      editor?.chain().focus().toggleHeading({ level }).run()
    } else {
      editor?.chain().focus().setParagraph().run()
    }
  }

  // Template
  return (
    <DropdownMenu>
      <Tooltip>
        <TooltipTrigger asChild>
          <DropdownMenuTrigger asChild>
            <Button className='gap-1' variant='ghost'>
              <TypeIcon />
              <ChevronDownIcon />
            </Button>
          </DropdownMenuTrigger>
        </TooltipTrigger>

        <TooltipContent>Text style</TooltipContent>
      </Tooltip>

      <DropdownMenuContent>
        {textStyles.map((textStyle) => (
          <DropdownMenuItem
            className={cn({
              'bg-accent text-accent-foreground': editorState?.isActive[`${textStyle.level}`]
            })}
            key={textStyle.level}
            onClick={() => changeTextStyle(textStyle)}
          >
            <span>{textStyle.label}</span>
            <DropdownMenuShortcut>{textStyle.shortcut}</DropdownMenuShortcut>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
})

TextStyleButton.displayName = 'TextStyleButton'
export default TextStyleButton

